  function pickScene(scenes, m) {
    const byId = id => scenes.find(s => s.id === id);
    const live = s => s && s.status === 'live';
    if (!m) return scenes.find(s => s.chapterDefault && live(s)) || null;
    const own = byId(m.sc);
    if (live(own)) return own;
    const home = scenes.find(s => s.home === m.s && live(s));
    if (home) return home;
    return scenes.find(s => s.chapter === m.c && s.chapterDefault && live(s)) || scenes.find(s => s.chapter === m.c && live(s)) || null;
  }
  function nextLiveScene(scenes, index, currentScene) {
    if (!currentScene || !Array.isArray(scenes) || !Array.isArray(index)) return null;
    const order = new Map(index.map((record, position) => [record.s, position]));
    const ids = new Set(), homes = new Set();
    const live = scenes.filter(scene => scene && scene.status === 'live' && scene.id && order.has(scene.home))
      .sort((a, b) => order.get(a.home) - order.get(b.home))
      .filter(scene => {
        if (ids.has(scene.id) || homes.has(scene.home)) return false;
        ids.add(scene.id); homes.add(scene.home); return true;
      });
    if (live.length < 2) return null;
    let at = live.findIndex(scene => scene.id === currentScene.id);
    if (at < 0) at = live.findIndex(scene => scene.home === currentScene.home);
    return at < 0 ? null : live[(at + 1) % live.length];
  }

